async function executeWithErrorHandling<T>(
  operation: () => Promise<T>,
  successMessage: string,
  errorPrefix: string
): Promise<void> {
  try {
    await operation();
    console.log(successMessage);
  } catch (error) {
    console.error(`${errorPrefix}:`, error);
    throw error;
  }
}

